  implementation 'com.rightware.kanzi:kzjava@aar'

  debugImplementation 'com.rightware.kanzi:kanzinative-debug@aar'
  releaseImplementation 'com.rightware.kanzi:kanzinative-release@aar'
  "profilingImplementation"('com.rightware.kanzi:kanzinative-profiling@aar')
}

```
